using System;
using System.IO;
using System.Linq;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine.SceneManagement;
namespace Snowglow.Editor {
 public static class HomeColliderAuthoring {
  const string Logs="Logs/HomeColliders",Request="Logs/HomeColliders.request",Tag="single-home-box";
  static int checks;
  static T[] All<T>(Scene s)where T:Component=>s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<T>(true)).ToArray();
  static bool Home(CatalogPlacement p)=>(p.assetId??"").StartsWith("winter-home-",StringComparison.Ordinal);
  static void Check(bool ok,string message){checks++;if(!ok)throw new InvalidOperationException("Home colliders: "+message);}
  static string Pose(Transform t)=>t.localToWorldMatrix.ToString("R");
  [InitializeOnLoadMethod]static void Register(){EditorApplication.update+=Pending;}
  static void Pending(){if(!File.Exists(Request)){EditorApplication.update-=Pending;return;}if(EditorApplication.isCompiling||EditorApplication.isUpdating||EditorApplication.isPlayingOrWillChangePlaymode)return;EditorApplication.update-=Pending;File.Delete(Request);try{Run();}catch(Exception e){Directory.CreateDirectory(Logs);File.WriteAllText(Logs+"/Validation.txt","FAIL: "+e);Debug.LogException(e);}}
  static void Remove(Collider c,bool undo){if(!c)return;UnityEngine.Object target=c;if(c.transform.childCount==0&&c.GetComponents<Component>().All(x=>x is Transform||x is Collider))target=c.gameObject;if(undo)Undo.DestroyObjectImmediate(target);else UnityEngine.Object.DestroyImmediate(target);}
  public static void PreparePrefab(CatalogAsset a){
   Check(a&&a.prefab,"home entry missing");if(a.tags.Contains(Tag)&&a.prefab.GetComponentsInChildren<Collider>(true).Length==1&&a.prefab.GetComponentInChildren<BoxCollider>(true))return;
   string path=AssetDatabase.GetAssetPath(a.prefab);var root=PrefabUtility.LoadPrefabContents(path);try{var bounds=CatalogValidation.BoundsOf(root);foreach(var c in root.GetComponentsInChildren<Collider>(true))Remove(c,false);var proxy=new GameObject("Collision | one enclosing home box");proxy.transform.SetParent(root.transform,false);var box=proxy.AddComponent<BoxCollider>();box.center=bounds.center;box.size=bounds.size;Check(box.size.x>0&&box.size.y>0&&box.size.z>0,"empty home bounds");PrefabUtility.SaveAsPrefabAsset(root,path);}finally{PrefabUtility.UnloadPrefabContents(root);}
   a.tags=a.tags.Concat(new[]{Tag}).Distinct().ToArray();a.status=PreparationStatus.NeedsReview;a.visualReviewed=false;a.reviewedPrefabHash="";a.assumptions+=" Collision revised to one solid enclosing box; placed lots use a full-height foundation box instead of duplicate home collision. Interiors/porches inside the footprint are not driveable.";CatalogPreparation.RecordMetrics(a);Check(CatalogValidation.Check(a).Ok,"catalog validation "+a.id);EditorUtility.SetDirty(a);
  }
  static Transform Foundation(CatalogPlacement home){for(var p=home.transform.parent;p;p=p.parent){var f=p.Find("Foundation");if(f)return f;}return null;}
  static Bounds BoundsIn(Transform frame,Renderer[] renderers){bool found=false;var result=new Bounds();foreach(var r in renderers){var b=r.localBounds;for(int n=0;n<8;n++){var local=b.center+Vector3.Scale(b.extents,new Vector3((n&1)==0?-1:1,(n&2)==0?-1:1,(n&4)==0?-1:1));var point=frame.InverseTransformPoint(r.transform.TransformPoint(local));if(found)result.Encapsulate(point);else{result=new Bounds(point,Vector3.zero);found=true;}}}Check(found,"missing render bounds");return result;}
  public static void ConfigureScene(Scene scene){foreach(var home in All<CatalogPlacement>(scene).Where(Home)){var foundation=Foundation(home);if(!foundation)continue;Check(foundation.GetComponent<Renderer>(),"foundation visual missing");var b=BoundsIn(foundation,home.GetComponentsInChildren<Renderer>(true).Concat(new[]{foundation.GetComponent<Renderer>()}).ToArray());foreach(var c in home.GetComponentsInChildren<Collider>(true))Remove(c,true);var boxes=foundation.GetComponents<Collider>();BoxCollider box=boxes.OfType<BoxCollider>().FirstOrDefault();foreach(var c in boxes.Where(c=>c!=box))Undo.DestroyObjectImmediate(c);if(!box)box=Undo.AddComponent<BoxCollider>(foundation.gameObject);Undo.RecordObject(box,"Enclose home with full-height foundation box");box.center=b.center;box.size=b.size;box.enabled=true;box.isTrigger=false;EditorUtility.SetDirty(box);if(PrefabUtility.IsPartOfPrefabInstance(box))PrefabUtility.RecordPrefabInstancePropertyModifications(box);}}
  [MenuItem("Snowglow/Environment/Use one enclosing box per home")]
  public static void Run(){checks=0;Check(!EditorApplication.isPlayingOrWillChangePlaymode,"stop Play");var scene=SceneManager.GetActiveScene();Check(scene.path==SceneValidation.ScenePath,"open Pinefall");Directory.CreateDirectory(Logs);string stamp=DateTime.Now.ToString("yyyyMMdd_HHmmss");Check(EditorSceneManager.SaveScene(scene,Logs+"/Pinefall-before-"+stamp+".unity",true),"scene backup");SceneValidation.Validate(scene);
   var homes=All<CatalogPlacement>(scene).Where(Home).ToArray();Check(homes.Length>0,"no homes");var entries=CatalogPreparation.Library().entries.Where(a=>a&&(a.id??"").StartsWith("winter-home-",StringComparison.Ordinal)).ToArray();Check(entries.Length==7,"seven catalog variants required");int before=homes.Sum(h=>h.GetComponentsInChildren<Collider>(true).Length+(Foundation(h)?Foundation(h).GetComponents<Collider>().Length:0));
   var poses=All<CatalogPlacement>(scene).Where(p=>!string.IsNullOrEmpty(p.placementId)).ToDictionary(p=>p.placementId,p=>Pose(p.transform));var visuals=All<Renderer>(scene).Where(r=>!(r is ParticleSystemRenderer)).ToDictionary(r=>GlobalObjectId.GetGlobalObjectIdSlow(r).ToString(),r=>Pose(r.transform));var fleet=All<MachineController>(scene).ToDictionary(m=>m.name,m=>Pose(m.transform));var snow=All<SnowField>(scene).Single();var original=snow.seed;string values=JsonUtility.ToJson(original.grid);var hashes=snow.GetComponentsInChildren<MeshFilter>().Select(m=>AssetDatabase.GetAssetPath(m.sharedMesh)).Concat(All<Terrain>(scene).Select(t=>AssetDatabase.GetAssetPath(t.terrainData))).Concat(new[]{AssetDatabase.GetAssetPath(original)}).Where(p=>!string.IsNullOrEmpty(p)).Distinct().ToDictionary(p=>p,p=>AssetDatabase.GetAssetDependencyHash(p));var fences=All<Collider>(scene).Where(c=>c.name.StartsWith("Fence",StringComparison.Ordinal)).Select(c=>GlobalObjectId.GetGlobalObjectIdSlow(c).ToString()).OrderBy(x=>x).ToArray();
   foreach(var a in entries){string path=AssetDatabase.GetAssetPath(a.prefab);File.Copy(path,Logs+"/"+a.id+"-before-"+stamp+".prefab");PreparePrefab(a);}Undo.IncrementCurrentGroup();int undo=Undo.GetCurrentGroup();bool saved=false;
   try{ConfigureScene(scene);Physics.SyncTransforms();Validate(scene);var revision=UnityEngine.Object.Instantiate(original);int changed=0;for(int i=0;i<revision.grid.blocked.Length;i++){bool blocked=Physics.CheckBox(new Vector3(revision.grid.X(i),SnowField.Ground+.85f,revision.grid.Z(i)),new Vector3(SnowVolumeGrid.Cell*.45f,.65f,SnowVolumeGrid.Cell*.45f),Quaternion.identity,1<<0,QueryTriggerInteraction.Ignore);if(blocked!=revision.grid.blocked[i]){revision.grid.blocked[i]=blocked;changed++;}}if(changed>0){AssetDatabase.CreateAsset(revision,AssetDatabase.GenerateUniqueAssetPath(CatalogPreparation.Root+"/SceneData/HomeBoxSnowObstacles.asset"));Undo.RecordObject(snow,"Bind home-box snow obstacle mask");snow.seed=revision;EditorUtility.SetDirty(snow);}else UnityEngine.Object.DestroyImmediate(revision);
    var mask=snow.seed.grid.blocked;snow.seed.grid.blocked=original.grid.blocked;Check(values==JsonUtility.ToJson(snow.seed.grid),"snow quantities changed");snow.seed.grid.blocked=mask;foreach(var p in All<CatalogPlacement>(scene).Where(p=>!string.IsNullOrEmpty(p.placementId)))Check(poses[p.placementId]==Pose(p.transform),"catalog moved "+p.placementId);foreach(var r in All<Renderer>(scene).Where(r=>!(r is ParticleSystemRenderer)))Check(visuals[GlobalObjectId.GetGlobalObjectIdSlow(r).ToString()]==Pose(r.transform),"visual transform changed");foreach(var m in All<MachineController>(scene))Check(fleet[m.name]==Pose(m.transform),"fleet moved");Check(fences.SequenceEqual(All<Collider>(scene).Where(c=>c.name.StartsWith("Fence",StringComparison.Ordinal)).Select(c=>GlobalObjectId.GetGlobalObjectIdSlow(c).ToString()).OrderBy(x=>x)),"fences changed");foreach(var h in hashes)Check(h.Value==AssetDatabase.GetAssetDependencyHash(h.Key),"original snow/terrain asset changed");SceneValidation.Validate(scene);MechanicsChecks.Run();AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);Check(EditorSceneManager.SaveScene(scene),"save");saved=true;Undo.CollapseUndoOperations(undo);scene=EditorSceneManager.OpenScene(SceneValidation.ScenePath);Physics.SyncTransforms();Validate(scene);SceneValidation.Validate(scene);MechanicsChecks.Run();foreach(var a in entries)Check(a.prefab.GetComponentsInChildren<Collider>(true).Length==1&&a.prefab.GetComponentInChildren<BoxCollider>(true),"catalog box not saved "+a.id);foreach(var p in All<CatalogPlacement>(scene).Where(p=>!string.IsNullOrEmpty(p.placementId)))Check(poses[p.placementId]==Pose(p.transform),"reopened placement moved");foreach(var h in hashes)Check(h.Value==AssetDatabase.GetAssetDependencyHash(h.Key),"original asset changed after reopen");
    File.WriteAllText(Logs+"/Validation.txt","PASS: Unity "+Application.unityVersion+" / "+EditorUserBuildSettings.activeBuildTarget+"; "+checks+" checks. "+homes.Length+" homes use one full-height foundation BoxCollider each; old house colliders removed. Home/foundation collider count "+before+" -> "+homes.Length+" (garden fences retained separately). Seven reusable prefabs now each have one enclosing box; placed homes override that duplicate because the foundation supplies collision. Roof/decorative snow/foundation bounds enclosed, native top raycasts passed. Renderers/meshes/materials, all catalog/fleet poses and fence colliders preserved. Saved/reopened Pinefall, scene validation and 19 snow checks passed. "+changed+" obstacle flags reconciled in separate seed revision; snow quantities and original seed/meshes/Terrain preserved. No district rebake, runtime assembly or player-save writes. Actual driving clearance and Android/A07 acceptance remain untested.");Debug.Log(File.ReadAllText(Logs+"/Validation.txt"));
   }catch{if(!saved)Undo.RevertAllDownToGroup(undo);throw;}
  }
  static void Validate(Scene s){foreach(var home in All<CatalogPlacement>(s).Where(Home)){var foundation=Foundation(home);Check(foundation,"lot foundation missing "+home.placementId);Check(home.GetComponentsInChildren<Collider>(true).Length==0,"duplicate home collision "+home.placementId);var colliders=foundation.GetComponents<Collider>();Check(colliders.Length==1&&colliders[0] is BoxCollider,"foundation box count");var box=(BoxCollider)colliders[0];Check(box.enabled&&!box.isTrigger,"non-solid box");var actual=new Bounds(box.center,box.size);var required=BoundsIn(foundation,home.GetComponentsInChildren<Renderer>(true).Concat(new[]{foundation.GetComponent<Renderer>()}).ToArray());Check((actual.center-required.center).magnitude<.002f&&(actual.size-required.size).magnitude<.002f,"enclosure mismatch "+home.placementId);for(int n=0;n<8;n++){var corner=required.center+Vector3.Scale(required.extents,new Vector3((n&1)==0?-1:1,(n&2)==0?-1:1,(n&4)==0?-1:1));Check(new Bounds(actual.center,actual.size+Vector3.one*.004f).Contains(corner),"roof/foundation outside box");}var centre=foundation.TransformPoint(box.center);Check(box.Raycast(new Ray(centre+foundation.up*100,-foundation.up),out var hit,200),"box top collision missing");Check(Vector3.Dot(hit.normal,foundation.up)>.99f,"box top normal");}}
 }
}
